No project code in working dir, so no file edited. Vanilla JS, assumes `#search` input and `/api/search?q=` endpoint:

```js
function debounce(fn, delay = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const input = document.querySelector('#search');
let controller;

async function search(query) {
  controller?.abort();
  if (!query.trim()) return renderResults([]);

  controller = new AbortController();
  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
      signal: controller.signal,
    });
    if (!res.ok) throw new Error(`Search failed: ${res.status}`);
    renderResults(await res.json());
  } catch (err) {
    if (err.name !== 'AbortError') throw err;
  }
}

input.addEventListener('input', debounce((e) => search(e.target.value), 300));
```

- Call fires 300 ms after last keystroke.
- `AbortController` cancels in-flight request, so slow old response never overwrites newer results. Debounce alone does not prevent that.
- `renderResults` is your existing render function.

React version, if that is your stack:

```jsx
import { useEffect, useState } from 'react';

function SearchInput() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  useEffect(() => {
    if (!query.trim()) {
      setResults([]);
      return;
    }
    const controller = new AbortController();
    const timer = setTimeout(async () => {
      try {
        const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
          signal: controller.signal,
        });
        if (!res.ok) throw new Error(`Search failed: ${res.status}`);
        setResults(await res.json());
      } catch (err) {
        if (err.name !== 'AbortError') console.error(err);
      }
    }, 300);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query]);

  return <input value={query} onChange={(e) => setQuery(e.target.value)} />;
}
```

Effect cleanup clears timer and aborts request on each keystroke and on unmount.
